def _q(b: int, n: int, d: str, p: str, c: str, w: list[str], e: str, h: str = '', fig=None):
    return make_q(f'HD4-B{b:02d}-{n:03d}', d, p, c, w, e, 'Hoạt động trải nghiệm 4', h, fig)


